package com.example.rebate.support;

import java.time.Instant;
import org.springframework.stereotype.Component;

/**
 * 统一时间源。生产环境返回系统 UTC 时间；测试可注入固定时刻以验证按 UTC 日界取文库版本。
 */
@Component
public class TimeService {

    private volatile Instant fixed;

    /**
     * 返回当前时刻（UTC）；测试固定后始终返回固定时刻。
     */
    public Instant now() {
        Instant f = fixed;
        return f != null ? f : Instant.now();
    }

    /**
     * 仅供测试：固定时钟。
     */
    public void setFixed(Instant instant) {
        this.fixed = instant;
    }

    /**
     * 仅供测试：恢复系统时钟。
     */
    public void reset() {
        this.fixed = null;
    }
}

package com.example.rebate.domain;

/**
 * 申报批次状态。
 *
 * <p>流转：校验通过 {@code CHECKED}；存在未解除疑点 {@code DOUBTFUL}；正式申报 {@code DECLARED}；
 * 审核通过 {@code APPROVED}；退库核销一致 {@code TREASURED}；到账差异转人工 {@code DIFF_MANUAL}；
 * 撤批整体作废 {@code VOID}；结案 {@code CLOSED}（终态）。</p>
 */
public enum BatchStatus {
    /** 关联校验完成、无疑点，可正式申报。 */
    CHECKED,
    /** 存在未解除疑点，禁止正式申报。 */
    DOUBTFUL,
    /** 已正式申报，批次冻结。 */
    DECLARED,
    /** 审核通过。 */
    APPROVED,
    /** 退库核销完成且金额一致。 */
    TREASURED,
    /** 到账差异超 0.5%，已登记差异并转人工。 */
    DIFF_MANUAL,
    /** 撤批整体作废，关联单证全部释放。 */
    VOID,
    /** 结案终态；重复结案幂等成功，迟到单证仅记事件。 */
    CLOSED
}

package com.example.rebate.domain;

/**
 * 批次-单证关联状态。
 */
public enum LinkStatus {
    /** 已关联到有效批次，单证被占用。 */
    LINKED,
    /** 已释放（撤批作废或创建批次失败回滚后不可见）。 */
    RELEASED
}

package com.example.rebate.domain;

/**
 * 疑点处理状态。
 */
public enum DoubtStatus {
    /** 校验产生疑点，等待企业补充说明。 */
    OPEN,
    /** 已提交说明，等待复核确认。 */
    EXPLAINED,
    /** 复核确认，疑点解除。 */
    RESOLVED
}

package com.example.rebate.domain;

/**
 * 单条关联校验结果。
 */
public enum CheckResult {
    /** 通过。 */
    PASS,
    /** 转疑点（如换汇成本越界、无匹配税率）。 */
    DOUBT
}

package com.example.rebate.domain;

/**
 * 单证类型。
 */
public enum DocType {
    /** 报关单。 */
    CUSTOMS,
    /** 进项发票。 */
    INVOICE
}

