                        (invoice_no, declaration_no, product_code, amount, collected_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    inv.invoiceNo(), inv.declarationNo(), inv.productCode(), inv.amount(),
                    java.sql.Timestamp.from(inv.collectedAt()));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
