                d.result().name(), d.doubtType());
        return jdbc.queryForObject("SELECT IDENTITY()", Long.class);
    }

    /**
     * 查询某批次全部校验明细。
     */
    public List<CheckDetail> findByBatchId(long batchId) {
        return jdbc.query(BASE_SELECT + " WHERE batch_id = ? ORDER BY id", MAPPER, batchId);
    }

