package com.example.rebate.web;

/**
 * 业务异常基类，携带 HTTP 状态码语义。
 */
public class ApiException extends RuntimeException {

    private final int status;

    public ApiException(int status, String message) {
        super(message);
        this.status = status;
    }

    public int getStatus() {
        return status;
    }
}

package com.example.rebate.web;

/**
 * 409 冲突：幂等指纹不一致、单证被其它有效批次占用、状态流转冲突等。
 */
public class ConflictException extends ApiException {

    public ConflictException(String message) {
        super(409, message);
    }
}

package com.example.rebate.web;

/**
 * 404 资源不存在。
 */
public class NotFoundException extends ApiException {

    public NotFoundException(String message) {
        super(404, message);
    }
}

package com.example.rebate.web;

/**
 * 422 业务校验失败（如疑点未解除即申报、终态后操作非法）。
 */
public class UnprocessableException extends ApiException {

    public UnprocessableException(String message) {
        super(422, message);
    }
}

package com.example.rebate.web;

import java.time.OffsetDateTime;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一异常响应。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * 业务异常按携带状态码返回。
     */
    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus()).body(body(ex.getStatus(), ex.getMessage()));
    }

    /**
     * Bean 校验失败统一 400。
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValid(MethodArgumentNotValidException ex) {
        String msg = ex.getBindingResult().getFieldErrors().stream()
                .findFirst()
                .map(e -> e.getField() + ": " + e.getDefaultMessage())
                .orElse("请求参数校验失败");
        return ResponseEntity.badRequest().body(body(400, msg));
    }

    /**
     * 兜底 500，不泄露堆栈。
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> handleOther(Exception ex) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(body(500, "服务内部错误"));
    }

    private static Map<String, Object> body(int status, String message) {
        return Map.of("timestamp", OffsetDateTime.now().toString(),
                "status", status, "error", message);
    }
}

package com.example.rebate.support;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import org.springframework.stereotype.Component;

/**
 * 幂等指纹：SHA-256，覆盖操作类型、requestId 与全部业务字段的规范化 JSON。
 */
@Component
public class FingerprintService {

    private final ObjectMapper canonicalMapper;

    public FingerprintService(ObjectMapper objectMapper) {
        // 复制一份并开启键排序，保证同参数不同字段顺序产生相同指纹。
        this.canonicalMapper = objectMapper.copy()
                .configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true)
                .configure(com.fasterxml.jackson.databind.MapperFeature.SORT_PROPERTIES_ALPHABETICALLY, true);
    }

    /**
     * 计算指纹：{@code SHA-256(opType | requestId | 规范化业务字段 JSON)}。
     */
    public String fingerprint(String opType, String requestId, Object payload) {
        String canonical;
        try {
            canonical = canonicalMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("幂等指纹序列化失败", e);
        }
        String raw = opType + '|' + requestId + '|' + canonical;
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(raw.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }

    /**
     * 将响应序列化为 JSON 文本存储，供同键重放原样返回。
     */
    public String toJson(Object response) {
        try {
            return canonicalMapper.writeValueAsString(response);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("响应序列化失败", e);
        }
    }
}

package com.example.rebate.service;

/**
 * 幂等操作结果。
 *
 * @param first {@code true} 首次执行；{@code false} 同键重放
 * @param status 首次或首次记录的 HTTP 状态码
