    @Transactional
    public BatchView withdraw(String batchNo) {
        DeclarationBatch batch = loadBatch(batchNo);
        if (batch.status() == BatchStatus.VOID) {
            return BatchViews.batch(batch);
        }
        if (batch.status() == BatchStatus.CLOSED) {
