                BigDecimal recalcCost =
                        RebateCalculator.exchangeCost(recalcBasis, d.fobUsd());
                boolean inRange = RebateCalculator.exchangeCostInRange(recalcCost);
                item.put("recalcVersionNo", resolved.versionNo());
